#include "../dpid-cuda/kernels.cu"
#include "../dpid-cuda/reference.h"
#include <fstream>
#include <vector>
#include <cstring>
#include <string>
#include <cstdlib>
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
const uchar3 sentinel=make_uchar3(165,90,195);
std::vector<unsigned char>load(std::string name,size_t n){std::vector<unsigned char>x(n);std::ifstream f("/home/imo/HeCBench_julia/src/dpid-julia/"+name,std::ios::binary);f.read((char*)x.data(),n);if(!f)exit(2);return x;}
uint32_t bits(float x){uint32_t u;memcpy(&u,&x,4);return u;}
struct Buffers{uchar3*ib,*gb,*ob;int n;Buffers(int count,const std::vector<unsigned char>&input):n(count){CHECK(cudaMalloc(&ib,(n+32)*3));CHECK(cudaMalloc(&gb,224*3));CHECK(cudaMalloc(&ob,224*3));std::vector<uchar3>h(n+32,sentinel);CHECK(cudaMemcpy(ib,h.data(),h.size()*3,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(ib+16,input.data(),n*3,cudaMemcpyHostToDevice));}~Buffers(){cudaFree(ib);cudaFree(gb);cudaFree(ob);}};
void launch(Buffers&b,Params p){dim3 block(128,1,1),grid((p.oWidth+3)/4,p.oHeight,1);kernelGuidance<<<grid,block>>>(b.ib+16,b.gb+16,p);kernelDownsampling<<<grid,block>>>(b.ib+16,b.gb+16,p,b.ob+16);}
int main(){static_assert(sizeof(uchar3)==3,"packedRGB");float lambda=getenv("STUDY_LAMBDA")?strtof(getenv("STUDY_LAMBDA"),nullptr):1.f;std::string label=lambda==0?"0":lambda==1?"1":"half";Params params[2]={{16,12,40,30,2.5f,2.5f,lambda,10},{16,12,128,96,8.f,8.f,lambda,10}};auto in1=load("study_input1_u8.bin",3600),in2=load("study_input2_u8.bin",36864);Buffers a(1200,in1),b(12288,in2);Buffers*buf[2]={&a,&b};std::vector<unsigned char>oracle[2],cpu_reference[2];for(int ci=0;ci<2;ci++){auto&g=oracle[ci];g=load("oracle_guidance"+std::to_string(ci+1)+"_u8.bin",576);auto out=load("oracle_output"+std::to_string(ci+1)+"_lambda_"+label+"_u8.bin",576);g.insert(g.end(),out.begin(),out.end());cpu_reference[ci].resize(576);auto&p=params[ci];auto&input=ci==0?in1:in2;reference(p.oWidth,p.oHeight,p.iWidth,p.iHeight,p.pWidth,p.pHeight,p.lambda,input.data(),cpu_reference[ci].data());launch(*buf[ci],p);}CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){std::vector<uint32_t>prefix,outputs,guards;double times[2];int err=0,source_cpu_err=0;bool ok=true;for(int ci=0;ci<2;ci++){auto&p=params[ci];auto&B=*buf[ci];std::vector<uchar3>sent(224,sentinel);CHECK(cudaMemcpy(B.gb,sent.data(),672,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(B.ob,sent.data(),672,cudaMemcpyHostToDevice));launch(B,p);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int j=0;j<10;j++)launch(B,p);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());times[ci]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;std::vector<unsigned char>input(B.n*3),actual(1152);CHECK(cudaMemcpy(input.data(),B.ib+16,input.size(),cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(actual.data(),B.gb+16,576,cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(actual.data()+576,B.ob+16,576,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),input.begin(),input.end());prefix.insert(prefix.end(),{p.oWidth,p.oHeight,p.iWidth,p.iHeight,bits(p.pWidth),bits(p.pHeight),bits(p.lambda),p.repeat});outputs.insert(outputs.end(),actual.begin(),actual.end());for(size_t i=0;i<actual.size();i++){int e=abs(int(actual[i])-int(oracle[ci][i]));err=std::max(err,e);ok&=e<=1;}for(size_t i=0;i<576;i++){int e=abs(int(actual[576+i])-int(cpu_reference[ci][i]));source_cpu_err=std::max(source_cpu_err,e);ok&=e<=1;}for(auto ptr:{B.ib,B.gb,B.ob}){size_t count=ptr==B.ib?B.n:192;std::vector<uchar3>raw(count+32);CHECK(cudaMemcpy(raw.data(),ptr,raw.size()*3,cudaMemcpyDeviceToHost));for(size_t j=0;j<16;j++){ok&=raw[j].x==165&&raw[j].y==90&&raw[j].z==195;guards.insert(guards.end(),{raw[j].x,raw[j].y,raw[j].z});}for(size_t j=count+16;j<count+32;j++){ok&=raw[j].x==165&&raw[j].y==90&&raw[j].z==195;guards.insert(guards.end(),{raw[j].x,raw[j].y,raw[j].z});}}}all&=ok;auto artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":2880,\"max_abs_error\":%d,\"max_rel_error\":null,\"source_CPU_reference_max_byte_error\":%d,\"timing_region\":\"sum_two_patch_regime_guidance_plus_downsampling_launch_loop_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"lambda\":%.9g,\"timed_cases\":2,\"component_time_seconds\":{\"fractional_2p5_patch\":%.12g,\"integer_8_patch\":%.12g},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",err,source_cpu_err,lambda,times[0],times[1],path.c_str(),artifact.size());}return all?0:1;}
